using System.Windows.Forms;
namespace AminPhoneBook { public class SettingsForm:Form { public SettingsForm(AppSettings s){Text="تنظیمات";Width=450;Height=300;StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20)};var dark=new CheckBox{Text="حالت تاریک",Checked=s.DarkMode,AutoSize=true};var auto=new CheckBox{Text="پشتیبان‌گیری خودکار",Checked=s.AutoBackup,AutoSize=true};var days=new NumericUpDown{Minimum=1,Maximum=90,Value=s.AutoBackupDays};var conf=new CheckBox{Text="تأیید قبل از حذف",Checked=s.ConfirmDelete,AutoSize=true};var save=new Button{Text="ذخیره",Width=100};p.Controls.AddRange(new Control[]{dark,auto,new Label{Text="دوره پشتیبان‌گیری (روز):"},days,conf,save});Controls.Add(p);save.Click+=(x,e)=>{s.DarkMode=dark.Checked;s.AutoBackup=auto.Checked;s.AutoBackupDays=(int)days.Value;s.ConfirmDelete=conf.Checked;DialogResult=DialogResult.OK;Close();};}}}